/** The questions an entry must be the first answer to. Used sparingly. */
export const HELP_PRIORITY:Partial<Record<HelpTopic,string>>={
 philosophy:'what is kanvas how do i use this what can you show philosophy what is this for',
};
export function helpFor(topic:HelpTopic,publicUrl:string,question?:string){const page=HELP_PAGES[topic],root=`${publicUrl.replace(/\/$/,'')}/docs/`;return {name:'Kanvas Help',version:KANVAS_VERSION,topic,...page,question,published:false,docs:{primary:root,topic:`${root}${topic}`,markdown:`${root}${topic}.md`,index:`${root}index.json`},...(topic==='orientation'?{choices:['Show something','Work with the current view','Share a screen']}:{}),agentInstruction:'Use this task-focused guidance with the user’s intent and live authorized state. Opening Help is not a request to publish. When an activity is authorized, carry it out with normal tools and real input/receipts; no fixed deck or repeated routine confirmations.'};}
